{
  "status": "NEEDS_IMPROVEMENT",
  "core_findings": [
    "Electronics has the weakest sampled positive–negative separation: negatives outrank positives at 15.96% of positions, and the 10th-percentile margin is −0.4829. Industrial_and_Scientific also has a negative lower-tail margin (−0.1961).",
    "CDs_and_Vinyl has the strongest sampled separation, with only 4.75% negative wins. Electronics has the greatest item-embedding directional alignment (0.7376), which alone does not establish representation collapse."
  ],
  "key_implications": [
    "The model ranks positives above sampled negatives at most measured positions in every dataset, with the largest weakness in Electronics.",
    "Embedding alignment varies across datasets, but these measurements cannot establish unhealthy training dynamics or reduced recommendation diversity.",
    "Sampled margins do not establish pinned validation HR@10, and unavailable perturbation results leave history sensitivity unmeasured."
  ],
  "evidence": {
    "headline_metrics": {
      "Electronics:pos_neg_neg_beats_pos_rate": 0.1596,
      "Electronics:pos_neg_margin_p10": -0.4829,
      "Industrial_and_Scientific:pos_neg_margin_p10": -0.1961,
      "CDs_and_Vinyl:pos_neg_neg_beats_pos_rate": 0.0475,
      "Electronics:embedding_collapse_score": 0.7376
    },
    "brief_metric_read": {
      "pos_neg_neg_beats_pos_rate": "Observed ranking errors against one sampled negative per valid position.",
      "pos_neg_margin_p10": "Negative values indicate lower-tail sampled ranking errors; magnitude depends on score scale.",
      "embedding_collapse_score": "Directional alignment above the approximately 0.5 orthogonal reference; not proof of collapse."
    }
  }
}
